@extends('layouts.storefront')
@section('title','Shop Crafts | MEETA')
@push('styles')<style>.page{padding-top:55px}.top{display:flex;justify-content:space-between;align-items:end}.top h1{font-size:44px;margin-bottom:5px}.sort{padding:11px;border:1px solid var(--line);background:#fff}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:35px}.card{border:1px solid var(--line);padding:9px;background:#fff}.card img{width:100%;height:260px;object-fit:cover}.card h3{font-size:18px;margin:14px 3px 7px}.meta{display:flex;justify-content:space-between;color:var(--brown);margin:0 3px 14px}.card button{width:100%}.empty{text-align:center;padding:100px}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:550px){.top{display:block}.grid{grid-template-columns:1fr}}</style>@endpush
@section('content')<main class="page wrap"><div class="top"><div><h1>Explore Handcrafted Stories</h1><p>Authentic pieces made by independent Indian artisans.</p></div><select id="sort" class="sort"><option value="latest">Newest</option><option value="price_low">Price: Low to High</option><option value="price_high">Price: High to Low</option></select></div><div id="grid"><div class="loading">Curating products…</div></div></main>@endsection
@push('scripts')<script>const params=new URLSearchParams(location.search);async function load(){params.set('sort',document.getElementById('sort').value);try{const {data}=await api('/api/customer/products?'+params.toString());document.getElementById('grid').innerHTML=data.items.length?`<div class="grid">${data.items.map(p=>`<article class="card"><a href="/products/${p.slug}"><img src="${p.image}" alt="${p.name}"><h3>${p.name}</h3></a><div class="meta"><span>₹${Number(p.effective_price).toLocaleString('en-IN')}</span><span>★ ${p.rating||'New'}</span></div><a class="btn primary" href="/products/${p.slug}">Choose Options</a></article>`).join('')}</div>`:'<div class="empty"><h2>No crafts found.</h2><a href="/shop">Clear filters</a></div>'}catch(e){toast(e.message)}}document.getElementById('sort').onchange=load;load();</script>@endpush
